-- Demo catalogue for local development.
--
-- These are the three products the Worker already knows about as LEGACY_BEATS
-- (see src/index.js) and for which artwork/preview files exist in public/. They
-- are inserted published so the storefront shows a working catalogue in the
-- sandbox. Media keys point at the objects uploaded to local R2 by
-- .base44/dev-setup.sh. INSERT OR IGNORE keeps re-runs harmless.
--
-- `zip_key` is a real, versioned package key — the same `-v<n>.zip` shape the
-- admin ZIP upload writes — and the matching archive is generated by
-- .base44/demo-packages.mjs and uploaded to local R2 BEFORE the licensing
-- migrations run. Without it migrations/0002_backfill_legacy_licence.sql cannot
-- grant the MP3 + WAV tier and GET /api/beat-licences returns nothing.
INSERT OR IGNORE INTO beats
  (id, title, genre, bpm, musical_key, price, description, artwork_key, preview_key, zip_key, status, featured, category)
VALUES
  ('sun-fire', 'SUN FIRE', 'Afrobeat', 102, 'F Minor', 7000,
   'Demo product seeded for local development. Replace it from the admin panel.',
   'artwork/sun-fire.jpg', 'previews/sun-fire.mp3', 'beats/sun-fire-v1.zip', 'published', 1, 'beats'),
  ('phenomenal', 'PHENOMENAL', 'Trap', 140, 'G Minor', 7000,
   'Demo product seeded for local development. Replace it from the admin panel.',
   'artwork/phenomenal.jpg', 'previews/phenomenal.mp3', 'beats/phenomenal-v1.zip', 'published', 0, 'beats'),
  ('serenade', 'SERENADE', 'R&B', 96, 'C Major', 7000,
   'Demo product seeded for local development. Replace it from the admin panel.',
   'artwork/serenade.jpg', 'previews/serenade.mp3', 'beats/serenade-v1.zip', 'published', 0, 'beats');

-- Sandboxes seeded before the demo packages existed already have these rows, so
-- INSERT OR IGNORE above left their zip_key NULL. Fill ONLY a missing key: a key
-- already on the row (an uploaded package, or one a purchase recorded) is never
-- replaced, so no historical package can be pointed away from its object.
UPDATE beats
   SET zip_key = 'beats/' || id || '-v1.zip',
       updated_at = CURRENT_TIMESTAMP
 WHERE category = 'beats'
   AND id IN ('sun-fire', 'phenomenal', 'serenade')
   AND (zip_key IS NULL OR TRIM(zip_key) = '');
